window.kbPageData["views/entry/k-4c66955c8eb9a866"] = {"key":"entry/k-4c66955c8eb9a866","state":{"route":"entry/k-4c66955c8eb9a866"},"node":{"id":"k-4c66955c8eb9a866","mode":"k","title":"三角形面积公式","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["三角形面积等于底与高乘积的一半","三角形面积等于底乘高的一半","三角形面积等于底乘对应高的一半","三角形面积等于底与对应高度乘积的一半"],"qs":["国考 2023 副省级 行测#67","国考 2023 行政执法 行测#62","国考 2025 副省级 行测#78","国考 2025 行政执法 行测#73"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":4,"repeatPositions":0,"directorySummary":"三角形的面积等于底与对应高的乘积的一半。对应高是底边所对顶点到该底边所在直线的垂直距离。","review":{"definition":"三角形的面积等于底与对应高的乘积的一半。对应高是底边所对顶点到该底边所在直线的垂直距离。","explanation":"梯形面积是三角形的 2 倍，所以三角形占正方形面积的三分之一。周长比与正方形的边长取值无关，可取边长为 3，此时三角形面积为 3。以 BE 为底，对应的高是与 BE 垂直的正方形边，长为 3，由 BE×3÷2＝3 得 BE＝2。正方形该边的剩余线段长为 1，规划线由勾股定理求得长为 √13，因此三角形与梯形的周长比为（5＋√13）∶（7＋√13），对应 D 项。","references":[],"evidence":"梯形土地的面积正好是三角形土地的2倍","disposition":"独立词条","basis":"据原题和解析编释。","title":"三角形面积公式","related":[],"examFocus":{"国考 2023 副省级 行测#67":"用三角形面积公式和勾股定理确定所需边长，比较两块土地的周长时都要计入共用的规划线。","国考 2023 行政执法 行测#62":"结合两块土地的面积关系，用三角形面积公式和勾股定理确定边长，再比较三角形与梯形的周长。","国考 2025 副省级 行测#78":"利用平行线间同底等高的三角形面积相等来处理阴影区域，注意题目以万平方米为单位。","国考 2025 行政执法 行测#73":"从图中的平行关系寻找可作等积替换的三角形，再用三角形面积公式求阴影面积，注意单位换算。"}},"readings":[{"origin":"k-4c66955c8eb9a866","title":"三角形面积公式","qs":["国考 2023 副省级 行测#67"],"definition":"三角形的面积等于底与对应高的乘积的一半。对应高是底边所对顶点到该底边所在直线的垂直距离。","explanation":"梯形面积是三角形的 2 倍，所以三角形占正方形面积的三分之一。周长比与正方形的边长取值无关，可取边长为 3，此时三角形面积为 3。以 BE 为底，对应的高是与 BE 垂直的正方形边，长为 3，由 BE×3÷2＝3 得 BE＝2。正方形该边的剩余线段长为 1，规划线由勾股定理求得长为 √13，因此三角形与梯形的周长比为（5＋√13）∶（7＋√13），对应 D 项。","evidence":"梯形土地的面积正好是三角形土地的2倍","doubt":"","references":[]},{"origin":"k-79bee3c1cd279a4f","title":"三角形面积公式","qs":["国考 2023 行政执法 行测#62"],"definition":"三角形的面积等于底与对应高的乘积的一半。直角三角形的两条直角边可以分别作为底和高。","explanation":"第62题中，梯形面积是三角形面积的2倍，所以三角形面积占正方形面积的三分之一。设正方形边长为3，则三角形面积为3。取与正方形边长相等的直角边为高，由面积公式得另一条直角边长为2。再用勾股定理求得两块土地共用的规划线长为√13，三角形与梯形的周长之比为（5＋√13）∶（7＋√13），对应D项。","evidence":"梯形土地的面积正好是三角形土地的2倍","doubt":"","references":[]},{"origin":"k-e0ebd1ede334b216","title":"三角形面积公式","qs":["国考 2025 副省级 行测#78"],"definition":"三角形的面积等于底长乘对应高的一半。任取一边为底，对应高是对顶点到底边所在直线的垂直距离，因此同底等高的三角形面积相等。","explanation":"第78题中，连接AE。由于EF与AB平行，三角形AFG与AEG同以AG为底，对应高均为BE，故面积相等。将阴影中的三角形AFG等积替换为三角形AEG，再与三角形ADG拼成三角形ADE。以AD为底，E到直线AD的垂直距离等于矩形的边长AB，所以阴影面积为240×100÷2＝12000平方米，即1.2万平方米，选A。AF的长度无需参与计算。","evidence":"AD、AB长度分别为240米、100米","doubt":"","references":[]},{"origin":"k-fcd27972a3822369","title":"三角形面积公式","qs":["国考 2025 行政执法 行测#73"],"definition":"三角形面积等于底边长度与对应高的乘积的一半。对应高是底边所对顶点到该底边所在直线的垂直距离。","explanation":"连接 AE。由于 EF∥AB，且 EB⊥AB，三角形 AFG 和 AEG 同以 AG 为底，高均为 EB，因此等面积。把阴影中的三角形 AFG 换成三角形 AEG，再与三角形 ADG 拼合。由于 E、G、D 共线，拼成三角形 ADE。以 AD 为底，E 到 AD 所在直线的垂直距离等于 AB，故阴影面积为 240×100÷2＝12000 平方米，即 1.2 万平方米，选 A。","evidence":"均以AG为底、EB为\n高，即两个三角形同底等高","doubt":"","references":[]}]},"questions":{"国考 2023 副省级 行测#67":{"paper":"国考 2023 副省级 行测","n":67,"mod":"数量关系","src":["503793642e845de9795f.pdf",12],"asrc":["ecade1ff5af69283232e.pdf",20],"card":"6bd03d5441e0d0210fea4ca0","links":[{"id":"k-4c66955c8eb9a866","role":"解题依据","why":"由面积比确定三角形面积，再用正方形边长作为对应的高反求底边。"}]},"国考 2023 行政执法 行测#62":{"paper":"国考 2023 行政执法 行测","n":62,"mod":"数量关系","src":["857378cf496f27296500.pdf",10],"asrc":["d23139fe5a0fb3115135.pdf",19],"card":"f94b027bb436e7bc8193c59f","links":[{"id":"k-4c66955c8eb9a866","role":"解题依据","why":"已知三角形的面积和一条直角边，可用面积公式求另一条直角边。"}]},"国考 2025 副省级 行测#78":{"paper":"国考 2025 副省级 行测","n":78,"mod":"数量关系","src":["ffe12c35a46d4df574ec.pdf",13],"asrc":["ff0b352b44d417525086.pdf",24],"card":"3a2e592375b4aee64b626691","links":[{"id":"k-4c66955c8eb9a866","role":"解题依据","why":"等积替换后可用三角形ADE求面积，其底是AD，高等于AB。"}]},"国考 2025 行政执法 行测#73":{"paper":"国考 2025 行政执法 行测","n":73,"mod":"数量关系","src":["d8efe4e19862104d89c8.pdf",12],"asrc":["e2c4b1970d2b49eac0fd.pdf",23],"card":"27b70bbed319511c0ad85cce","links":[{"id":"k-4c66955c8eb9a866","role":"解题依据","why":"用矩形的邻边长度作为等面积三角形的底和高。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-4c66955c8eb9a866":[["国考 2023 副省级 行测#67"],["国考 2023 行政执法 行测#62"],["国考 2025 副省级 行测#78"],["国考 2025 行政执法 行测#73"]]}};
